import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text()
def load(p): return json.loads(read(p))
def test_release_identity_m265():
 d=load('data/release_identity.json'); assert d['milestone'] in {'M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['client_version'] in {'0.265.0','0.266.0','0.268.0','0.269.0','0.270.0','0.271.0','0.272.0','0.273.0','0.274.0','0.275.0','0.276.0','0.277.0','0.278.0','0.279.0','0.280.0','0.281.0','0.282.0','0.283.0','0.284.0','0.285.0','0.286.0','0.287.0','0.288.0','0.289.0','0.290.0','0.291.0','0.292.0','0.293.0','0.294.0','0.295.0','0.296.0','0.297.0','0.298.0','0.299.0','0.300.0','0.301.0'} and d['build_number'] in {265,266,267,268,269,270,271,272,273,274,275,276,277,278,279,280,281,282,283,284,285,286,287,288,289,290,291,292,293,294,295,296,297,298,299,300,301} and d['content_config_version'] in {'M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['master_concept']=='V3.8' and 'M265' in d['visual_master_lock']
def test_contract_server_profile_ownership_fail_closed():
 d=load('data/m265_player_profile_ownership_contract.json'); p=d['principles']; assert p['profile_truth_is_server_authoritative'] and p['ownership_truth_is_server_authoritative'] and p['equipped_state_must_reference_owned_instances'] and p['writes_use_expected_revision_and_idempotency'] and p['test_global_isolated']; assert all(v is None for v in d['configuration'].values()); assert d['safety']['client_can_grant_ownership'] is False and d['safety']['client_can_set_wallet_balance'] is False and d['safety']['client_can_equip_unowned_instance'] is False
def test_runtime_monotonic_identity_and_request_only():
 s=read('scripts/online/m265_player_profile_ownership_runtime.gd'); assert 'if not server_verified: return false' in s and 'incoming_revision <= revision' in s and 'account_id != _account_id' in s and 'captain_id != _captain_id' in s and 'environment != _environment' in s and 'CLIENT_REQUEST_ONLY' in s and '"committed":false' in s; assert all(f'func {x}' in s for x in ['can_client_grant_ownership','can_client_revoke_ownership','can_client_set_wallet_balance','can_client_set_progression','can_client_confirm_profile_commit','can_client_equip_unowned_instance','can_client_transfer_test_ownership_to_global'])
def test_bootstrap_command_deck_admin_integration():
 b=read('scripts/core/game_bootstrap.gd'); c=read('scripts/ui/command_deck.gd'); assert 'M265PlayerProfileOwnershipRuntime.new()' in b and 'PlayerProfileOwnershipReadiness' in b and 'PLAYER PROFILE · OWNERSHIP · PERSISTENCE' in c and 'M265PlayerProfileOwnershipCatalog.overview' in c; a=load('data/admin_content_type_registry.json'); assert a['milestone'] in {'M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and all(x in a['content_types'] for x in ['player_profile_schema_definition','ownership_instance_policy_definition','loadout_integrity_policy_definition','profile_transaction_policy_definition'])
def test_convergence_advances_honestly():
 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['authoritative_player_profile_ownership_persistence']; assert row['status']=='PARTIAL' and 'm265_fix' in row and 'production player-profile repository' in row['remaining']
